/// Verifies that a buffer of bytes contains a `SCR`
/// and returns it.
/// Note that verification is still experimental and may not
/// catch every error, or be maximally performant. For the
/// previous, unchecked, behavior use
/// `root_as_scr_unchecked`.
#[inline]
pub fn root_as_scr(buf: &[u8]) -> Result<SCR<'_>, ::flatbuffers::InvalidFlatbuffer> {
    ::flatbuffers::root::<SCR>(buf)
}

